#!/usr/bin/env python3
"""Generate sfx/README.md from manifest.json + qa_report.json (so the numbers in the README are the measured numbers). usage: python3 make_readme.py"""
import json
import os
HERE = os.path.dirname(os.path.abspath(__file__))
man = json.load(open(os.path.join(HERE, "manifest.json")))
qa = json.load(open(os.path.join(HERE, "qa_report.json"))) if os.path.exists(os.path.join(HERE, "qa_report.json")) else {}
S = man["sounds"]
cats = {}
for d in S:
    cats.setdefault(d["category"], []).append(d)
ORDER = ["whoosh", "impact", "riser", "ui", "glass", "metal", "wood", "paper", "cloth", "plastic", "camera", "cash", "sparkle", "liquid", "cartoon", "voice", "drum", "transition", "stinger", "logo", "ambience", "indian", "foley", "device", "crowd", "elec"]
BLURB = {
    "whoosh": "Band-passed noise, exponential fc sweep, skewed-bell amplitude, air + body layers, pan path. Anchor = loudest sample = put it on the frame of maximum on-screen velocity.",
    "impact": "Hits and booms: tonal crest + noise crack + sub. Hero hits (tier 1) at most one per 8-10 s.",
    "riser": "Risers / downlifters. Riser lengths are whole bars at 120 BPM; the anchor is the END: place so it lands one frame before the hit (manifest `anchor_frame_offset = -1`).",
    "ui": "Clicks, pops, blips, typing, counters, snaps (tonal ones in A major).",
    "glass": "Modal glass / ceramic / crack / shatter.", "metal": "Modal steel plate, FM ping, scrape.", "wood": "Wood block, tap, door knock, creak.", "paper": "Grain-cloud paper rustle / crumple / page flip.",
    "cloth": "Swish, flap, footstep.", "plastic": "Plastic tap, light switch.", "camera": "Shutter.", "cash": "Ka-ching.", "sparkle": "Sparkle shimmer, sizzle grains.",
    "liquid": "Minnaert bubble model: bubble, drip, pour, splash, glug, fizz.",
    "cartoon": "Cartoon motion (pitch follows motion; one sound per action beat): boings, squeaks, slide whistles, tiptoe, bonk, poof, sad brass, record scratch, rimshot...",
    "voice": "WORD-FREE character voices (glottal source + formant bank): chirps, grunts, 'oh', 'huh', 'hmm', giggle, gasp, sigh, babble. No speech, no TTS.",
    "drum": "Drum voices shared with the music kit.", "transition": "Sweeteners: the sound of each edit type (see `sweeteners.json`).",
    "stinger": "Short punctuation (reveal, win, alert, cut-to-black, question, bump).", "logo": "Sonic logos (anchor = the landing note).",
    "indian": "Indian instruments, owned synthesis (`mpaudio/indian.py`): tabla bols (dayan harmonic modal bank after Raman 1920, bayan heuristic exponential glide), sitar (Karplus-Strong + jawari + tarab bank), santoor, shehnai-like and bansuri-like leads, harmonium, shruti drone, conch, temple bell, thali, manjira, ghungroo, dholak, nagara, dhol. Tuned to Sa = A, just intonation.",
    "foley": "Foley with 4 round-robin takes each (seeds s..s+3; the mixer picks seed + occurrence): footsteps on concrete / wood / gravel / carpet, doors, drawer, chair, keys, coin, cups, chai glasses, pen, stamp, zipper, scissors, tape, paper tear, book, laptop.",
    "device": "Phone, desktop and app sounds: buzz, original ringtone, message sent / received, mouse, mechanical keys (2 switch types, round-robin), loading tick, progress fill, card flip, level up, achievement, lock / unlock, notification dings.",
    "crowd": "WORD-FREE synthetic crowd reactions from the formant voices (cheer, aww, boo). No speech, no recordings.",
    "elec": "Electric (arc zap, sustained crackle loop, zap-off power-down) for neon / electric outline type and power-on moments: a crack, filtered-noise bursts and micro-crackles, and a raspy mains-style buzz tuned to A2 (110 Hz, the pack key) whose level follows a seeded random walk (a Brownian bridge in the 4.0 s loop so it wraps).",
    "ambience": "Seamless 8.0 s loops (circular synthesis / equal-power self cross-fade). Level them with the mixer (about -10 dB re the bed).",
}
L = []
A = L.append
A("# motion-pack / sfx : the synthesised sound library (owned, reusable)")
A("")
A("%d sounds in %d families, all generated by code (numpy / scipy / numba): no samples, no downloads, no speech, no paid generation. 48 kHz, 24-bit WAV, stereo, peak-normalised to -6 dBFS, trimmed, edge-faded. "
  "`manifest.json` has id, category, tags, duration, anchor, peak, true peak, LUFS (integrated / momentary max / short-term max), spectral centroid, crest, suggested over-bed level, "
  "pairing transitions, roles, phone-safety and a SHA of the deterministic render for every sound. Ideas reused (re-written, not vendored): ANVE's v9 launch-film SFX script (TPT filter, sin^2 attack envelopes, "
  "equal-power pan, IR), `mix9.py` (hit contract, over-bed solver, limiter), `spec-to-loop/scripts/measure_audio.py` (BS.1770 meter)." % (man["count"], len(cats)))
A("")
A("## Build, test, listen-free QA")
A("```bash")
A("cd sfx")
A("python3 build_library.py            # renders library/<family>/<id>.wav + manifest.json (about 10 s)")
A("python3 qa.py                       # determinism, finite, peak, DC, start/end edges, sub energy, centroid per family, seed variation, loop seams, python-vs-ffmpeg ebur128")
A("python3 tests/test_primitives.py    # svf -3 dB, noise colours, Karplus-Strong pitch, BS.1770 vs ffmpeg, limiter ceiling, anchor contract (F+1 frames)")
A("python3 demo/demo_sfx_reel.py       # 20 s reel, one cue per family, mastered -14 LUFS / <= -1.5 dBTP -> demo/out/sfx_reel.wav")
A("python3 demo/contact_sheet.py       # spectrogram contact sheets -> demo/stills/*.jpg (visual check of sweeps, envelopes, bandwidth)")
A("python3 make_readme.py              # regenerates this file from the measured manifest")
A("python3 tools/listening_checklist.py # writes LISTENING_PASS.md: the by-ear checklist (nothing has been auditioned yet)")
A("python3 tools/check_origin.py DIR    # provenance gate for any IMPORTED audio: ORIGIN.txt (url, author, licence, snapshot, date, zip sha) + licence allow-list; exit 2 = refused")
A("python3 tools/catalog_import.py DIR --category NAME [--dry]   # normalise approved external WAVs (48k/24-bit, -6 dBFS) + same measurements, tagged source:ext, into library_ext/ (never manifest.json)")
A("```")
fails = len(qa.get("fails", []))
A("")
A("QA status at build: **%d sounds, %d fails, %d warnings**; cross-meter max |python - ffmpeg ebur128| on every sound of 1.5 s or more = %s LU (limit 0.1)." % (
    qa.get("count", man["count"]), fails, len(qa.get("warns", [])), max([r.get("dI", 0) for r in qa.get("rows", [])] or [0])))
A("")
A("## The contract (so every motion component can attach sound)")
A("- **Anchor.** Each sound has `anchor_sample` (also `anchor_ms`): the designated peak / impact. A cue whose VISUAL frame is F puts the anchor on sample **(F + 1) x 48000 / fps** (one frame after the picture, the v9 rule). Risers end one frame BEFORE the hit anchor (`anchor_frame_offset = -1`).")
A("- **Determinism.** `render(id, seed)` is a pure function; the same code and seed give identical bytes (`sha` in the manifest). The mixer uses seed + occurrence index for round-robin variants.")
A("- **Level.** Library level is -6 dBFS peak (headroom for layering). Real levels are solved by `music/mixer.py` against the bed: hero +4.5, whoosh +2, ui +4, logo +5 dB (K-weighted, 60 ms); `over_bed_db` in the manifest is the default.")
A("- **Phone check.** `phone_safe=false` (voiced level drops > 6 dB on a phone speaker) means a sub-heavy sound: pair it with a mid-range cue (mixer lint R12).")
A("- **Use from Python.**")
A("```python")
A("import sys; sys.path.insert(0, 'music'); import mixer")
A("m = mixer.Mix(fps=30, length_s=12); m.add_bed(bed_audio)           # bed: float (n,2) at 48 kHz")
A("m.add_cue('snd.hit.thud', frame=60)                                  # anchor lands on sample 61 x 1600")
A("m.add_transition('whip', frame=120, duration_frames=8, energy=0.6)  # sweetener table -> cues")
A("rep = m.render('out_dir')                                           # master.wav -14 LUFS / -1.5 dBTP, stems, report with measured over-bed per cue")
A("```")
A("- **Bundles**: `bundles.json` (from `bundles.py`) maps cue ROLES to ids per video type: " + ", ".join(k for k, v in json.load(open(os.path.join(HERE, "bundles.json"))).items() if isinstance(v, dict)) + " (plus bed presets, BPM range, level notes). Ids are validated against the manifest.")
A("- **Loops under a state**: a loop cue runs to the end of the mix unless it gets `until_frame` (`Mix.add_cue(sid, frame, until_frame=F)`, or `\"until_frame\"` in a cue sheet): e.g. `snd.ui.agent_working` under one \"AI at work\" state, stopped with a 40 ms fade on the result frame.")
A("- **Transition sweeteners**: `mpaudio/sweeteners.py` -> `sweeteners.json` (kind -> sound, anchor position, tier, over-bed). Transition kinds: " + ", ".join(sorted(man["by_transition"])) + ".")
A("  The 5 formerly pending pairings (shutter, swipeUp, spin, pagePeel, pixelSort) and dip are explicit rows; a kind with no row (new visual transitions) falls back to its `transitions/catalog.json` sfx list (`source: transitions/catalog.json` in sweeteners.json; loops are never used as sweeteners).")
A("- **Round robin**: ids tagged `rr:4` (foley, tabla, keyboard, mouse...) have four useful takes: seeds s..s+3. The mixer already uses seed + occurrence for a repeated id.")
A("")
A("## Tags")
A("`family:*`, `size:{xs,s,m,l,xl}`, `tier:{1,2,3}`, `anchor:{crest,noise,scatter,end,start,loop}`, `tonal:{yes,no}`, `key:A`, `mood:*`, plus modifiers (`sub`, `reverse-swell`, `wordless`, `foley`, `loop`...). `manifest.json` -> `by_tag` and `by_transition` are ready-made indexes.")
A("")
A("## Library (measured)")
A("Columns: dur s | anchor ms | LUFS-M max | centroid Hz | crest dB | use | pairs with (transitions) | flags. All sounds are normalised to -6 dBFS peak.")
for c in ORDER:
    if c not in cats:
        continue
    A("")
    A("### %s (%d)" % (c, len(cats[c])))
    A(BLURB.get(c, ""))
    A("")
    A("| id | what | dur | anchor | LUFS-M | centroid | crest | use | pairs | tags / flags |")
    A("|---|---|---|---|---|---|---|---|---|---|")
    for d in sorted(cats[c], key=lambda z: z["id"]):
        flags = [t for t in d["tags"] if t.startswith(("tier", "size", "anchor", "tonal", "mood", "key"))]
        if d.get("phone_safe") is False:
            flags.append("phone:weak")
        if d["loop"]:
            flags.append("loop")
        A("| `%s` | %s | %.2f | %s | %.1f | %d | %.0f | %s | %s | %s |" % (d["id"].replace("snd.", ""), d["desc"].replace("|", "/"), d["duration_s"], ("%.0f" % d["anchor_ms"]) if not d["loop"] else "loop", d["lufs_m_max"], d["centroid_hz"],
                                                                        d["crest_db"], ",".join(d["use"][:3]), ",".join(d["pairs_with"][:3]), " ".join(flags)))
A("")
A("## Honest limits")
A("- **Nothing here was auditioned by a human yet.** Defaults are starting values from DSP practice; the QA is measurement (spectra, loudness, edges, determinism) plus spectrogram stills. Do one listening pass per new family before shipping a film; record one line per family here.")
A("- Glass / bell / metal / bubble / formant numbers come from textbook or remembered tables (docs/evidence/sound.md grades C): they may need retuning by ear. The word-free voices are formant-synth stylisations, not real voices.")
A("- Platform loudness: only Spotify (-14 LUFS, -1 dBTP) and YouTube normalisation behaviour are documented; Instagram / TikTok / X / LinkedIn are D-grade: house master is -14 LUFS-I / <= -1.5 dBTP (AAC probes <= -1.0) and still needs the empirical upload test (docs/evidence/sound.md 5.3).")
A("- 2026-10-13 expansion (+100 sounds: indian 26, foley 20, device 16, ui +5 voice-assistant, impacts +6, risers +5, whooshes +4, ambience +11, crowd 3, cartoon +4) is equally unheard: see `LISTENING_PASS.md`. Indian voices are stylised synthesis (no samples, no imitation of recordings); crowd sounds are word-free formant voices.")
A("- Spectral-centroid ranges and sub-energy limits in `qa.py` are sanity guards (warn), not perceptual claims.")
open(os.path.join(HERE, "README.md"), "w").write("\n".join(L) + "\n")
print("README.md", len(L), "lines")
